cases.update:
base <http://example.com/resource/>
prefix em: <http://example.com/resource/ontology/>
insert {
  graph <relations> { ?company em:parent ?other. ?other em:subsidiary ?company }
} where {
  values ?type {<relation/parent> <relation/acquisition>}
  [em:type ?type; em:company ?company; em:investor ?other]
};
insert {
  graph <relations> { ?company em:hasCompetitor ?other. ?other em:hasCompetitor ?company. }
} where {
  [em:type <relation/competition>; em:company ?company; em:company ?other]
  filter(str(?company)<str(?other)) 
};

